import 'package:flutter/material.dart';

import 'bi_theme.dart';

/// Displays the rule-based "AI Insights" and "Recommendations" lists
/// generated by [SalesAnalyticsService].
class BiInsightsRecommendations extends StatelessWidget {
  final List<String> insights;
  final List<String> recommendations;

  const BiInsightsRecommendations({
    super.key,
    required this.insights,
    required this.recommendations,
  });

  @override
  Widget build(BuildContext context) {
    final isWide = MediaQuery.sizeOf(context).width >= 700;

    final insightsCard = _InsightCard(
      title: 'AI Insights',
      icon: Icons.auto_awesome_rounded,
      accentColor: BiColors.info,
      items: insights,
      emptyText: 'Not enough data yet to generate insights.',
    );

    final recommendationsCard = _InsightCard(
      title: 'Recommendations',
      icon: Icons.lightbulb_rounded,
      accentColor: BiColors.warning,
      items: recommendations,
      emptyText: 'No recommendations right now.',
    );

    if (isWide) {
      return Row(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Expanded(child: insightsCard),
          const SizedBox(width: 16),
          Expanded(child: recommendationsCard),
        ],
      );
    }

    return Column(
      children: [
        insightsCard,
        const SizedBox(height: 16),
        recommendationsCard,
      ],
    );
  }
}

class _InsightCard extends StatelessWidget {
  final String title;
  final IconData icon;
  final Color accentColor;
  final List<String> items;
  final String emptyText;

  const _InsightCard({
    required this.title,
    required this.icon,
    required this.accentColor,
    required this.items,
    required this.emptyText,
  });

  @override
  Widget build(BuildContext context) {
    return BiGlassCard(
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Icon(icon, color: accentColor, size: 18),
              const SizedBox(width: 8),
              Text(
                title,
                style: const TextStyle(
                  color: BiColors.white,
                  fontSize: 15.5,
                  fontWeight: FontWeight.w700,
                ),
              ),
            ],
          ),
          const SizedBox(height: 14),
          if (items.isEmpty)
            Text(
              emptyText,
              style: TextStyle(color: BiColors.white.withOpacity(0.6), fontSize: 13),
            )
          else
            for (final item in items)
              Padding(
                padding: const EdgeInsets.only(bottom: 10),
                child: Row(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Container(
                      margin: const EdgeInsets.only(top: 6, right: 10),
                      width: 6,
                      height: 6,
                      decoration: BoxDecoration(
                        color: accentColor,
                        shape: BoxShape.circle,
                      ),
                    ),
                    Expanded(
                      child: Text(
                        item,
                        style: const TextStyle(
                          color: BiColors.white,
                          fontSize: 13,
                          height: 1.35,
                        ),
                      ),
                    ),
                  ],
                ),
              ),
        ],
      ),
    );
  }
}
